    if (w.endsWith('iest') && w.length > 5) add(w.slice(0, -4) + 'y');
    if (w.endsWith('er') && w.length > 3) add(w.slice(0, -2));
    if (w.endsWith('est') && w.length > 4) add(w.slice(0, -3));
    if (w.endsWith('ly') && w.length > 3) add(w.slice(0, -2));
